414  free_packet (PACKET *pkt, PARSER_CTX *parsectx)
415  {
416    if (!pkt->pkt.generic)
417      {
418        if (parsectx)
419          {
420            /* We need to skip the rest of the packet because we
421             * haven't read it yet.  */
422            iobuf_skip_rest (parsectx->sb, parsectx->last_pktlen, 0);
423            parsectx->last_pktlen = 0;
424          }
425        return;
426      }
427
428    switch (pkt->pkttype)
429      {
430      case PKT_PUBKEY_ENC: free_pubkey_enc(pkt->pkt.pubkey_enc); break;
431      case PKT_SYMKEY_ENC: free_symkey_enc(pkt->pkt.symkey_enc); break;
432      case PKT_ENCRYPTED: free_encrypted(pkt->pkt.encrypted); break;
433      case PKT_PLAINTEXT: free_plaintext(pkt->pkt.plaintext); break;
434      case PKT_COMPRESSED: free_compressed(pkt->pkt.compressed); break;
435      case PKT_ENCRYPTED_MDC: free_encrypted_mdc(pkt->pkt.encrypted_mdc); break;
436      case PKT_ONEPASS_SIG: free_onepass_sig(pkt->pkt.onepass_sig); break;
437      case PKT_SIGNATURE: free_signature(pkt->pkt.signature); break;
438      case PKT_RING_TRUST: free_ring_trust(pkt->pkt.ring_trust); break;
439      case PKT_PUBLIC_KEY: free_public_key(pkt->pkt.public_key); break;
440      case PKT_SECRET_KEY: free_secret_key(pkt->pkt.secret_key); break;
441      case PKT_USER_ID: free_user_id(pkt->pkt.user_id); break;
442      case PKT_ATTRIBUTE: free_attr(pkt->pkt.user_id); break;
443      case PKT_COMMENT: free_comment(pkt->pkt.comment); break;
444      case PKT_GPG_CONTROL: free_gpg_control(pkt->pkt.gpg_control); break;
445      default: log_bug ("invalid pkttype in free_packet\n");
446      }
447    pkt->pkt.generic = NULL;
448    pkt->pkttype = 0;
449  }
